//! Replays `retry_after_cases` from the golden corpus generated by
//! `electricity/scripts/generate_http_conventions_corpus.py` -- real
//! output from `circuitry.adapters._retry::parse_retry_after_seconds`
//! (RFC 9110 section 10.2.3, issue #778 step 7) -- against this crate's
//! own `retry::parse_retry_after_seconds_at`.
//!
//! The rest of that corpus (`scheme_detection_cases`/`strict_port_cases`/
//! `redaction_cases`/`proxy_cases`) is replayed by `electricity-tools`'s
//! own `tests/http_conventions_corpus.rs` instead -- this crate depends
//! on `electricity-tools`, never the other way around, and
//! `parse_retry_after_seconds_at` lives here, not there; both test files
//! read the same committed JSON file (`electricity-tools/tests/golden/
//! http_conventions_corpus.json` -- this crate has no `tests/golden/`
//! copy of its own).
//!
//! The corpus is checked in; CI separately regenerates it with Python
//! 3.11 and fails the build if it differs
//! (`.github/workflows/electricity-generated.yml`), so this test only
//! needs to trust the committed file.

use electricity_vm::retry::parse_retry_after_seconds_at;

fn load_corpus() -> serde_json::Value {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../electricity-tools/tests/golden/http_conventions_corpus.json");
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    serde_json::from_str(&text).expect("valid JSON")
}

#[test]
fn retry_after_cases_match_cof() {
    let corpus = load_corpus();
    for case in corpus["retry_after_cases"].as_array().unwrap() {
        let now_text = case["now"].as_str().unwrap();
        let now = chrono::DateTime::parse_from_rfc3339(now_text)
            .unwrap()
            .with_timezone(&chrono::Utc);
        let value = case["value"].as_str().unwrap();
        let actual = parse_retry_after_seconds_at(value, now);
        match case["seconds"].as_str() {
            Some("inf") => assert_eq!(actual, Some(f64::INFINITY), "case: {case:?}"),
            Some(other) => panic!("unexpected string seconds {other:?} in case: {case:?}"),
            None => match case["seconds"].as_f64() {
                Some(expected) => {
                    assert_eq!(actual, Some(expected), "case: {case:?}");
                }
                None => assert_eq!(actual, None, "case: {case:?}"),
            },
        }
    }
}
